# Analyze baseline answers: cutoff rate, frequent words in failed vs finished
import json, re
from collections import Counter
rows = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
print(len(rows))
cut = [r for r in rows if r['finish'] != 'stop']
print('finish values:', Counter(r['finish'] for r in rows))
print('cut:', len(cut), 'correct:', sum(r['correct'] for r in rows)/len(rows))
fin = [r for r in rows if r['finish']=='stop']
print('finished correct:', sum(r['correct'] for r in fin)/len(fin))
# word frequency per 1000 tokens, line-initial words
def line_words(t):
    return re.findall(r'(?m)^\s*([A-Za-z]+)', t)
def all_words(t):
    return re.findall(r'[A-Za-z]+', t.lower())
for group, name in [(cut,'cut'), (fin,'fin')]:
    c = Counter()
    tot = sum(r['tokens'] for r in group)
    for r in group:
        for w in line_words(r['text']):
            c[w.lower()] += 1
    print(name, 'tot tokens', tot)
    for w,n in c.most_common(15):
        print('  ', w, round(n*1000/tot,2))

for n in ['model.language_model.layers.0.input_layernorm.weight','model.language_model.layers.11.post_attention_layernorm.weight','model.language_model.layers.0.linear_attn.norm.weight','model.language_model.norm.weight']:
    w = load_original(n)
    print(n, 'mean', w.mean().item(), 'std', w.std().item(), 'min', w.min().item(), 'max', w.max().item())

for r in sorted(fin, key=lambda r:r['tokens'])[:2]:
    print('='*20, r['qid'])
    print(r['prompt'])

